WITH exploded AS (SELECT t.id, t.coupon_codes, pos + 1 AS position, elem.product_id, elem.price, elem.promo FROM carts t LATERAL VIEW OUTER POSEXPLODE(t.items) x AS pos, elem) SELECT CASE WHEN product_id >= 11 THEN 'HIGH' ELSE 'LOW' END AS product_id_tier, COUNT(*) FILTER (WHERE promo = 'WELCOME5') AS welcome5_rows, COUNT(CASE WHEN promo = 'SPRING10' THEN 1 END) AS spring10_count FROM exploded GROUP BY 1 ORDER BY product_id_tier DESC NULLS LAST;
